// Parse the Claude output into a JSON array of 6 day posts
const aiText = $input.first().json.text || $input.first().json.output || '';

let parsed;
try {
  parsed = JSON.parse(aiText);
} catch {
  // Try to extract JSON array from the response
  const jsonMatch = aiText.match(/\[\s*\{[\s\S]*\}\s*\]/);
  if (jsonMatch) {
    try {
      parsed = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      throw new Error(`Failed to parse AI output: ${e2.message}`);
    }
  } else {
    throw new Error(`No JSON array found in AI output: ${aiText.substring(0, 300)}`);
  }
}

if (!Array.isArray(parsed)) {
  throw new Error('Output is not an array');
}

console.log(`Parsed ${parsed.length} posts`);

// Validate and normalize fields
const requiredFields = ['day', 'postCaption', 'imagePrompt', 'videoIdea'];
const contentFormats = {
  'Monday': 'Storytelling',
  'Tuesday': 'Statistics',
  'Wednesday': 'Customer Testimonial',
  'Thursday': 'How It Works',
  'Friday': 'Behind the Scenes',
  'Saturday': 'Thought Leadership'
};

const normalized = parsed.map((post, i) => {
  for (const field of requiredFields) {
    if (!post[field]) {
      console.warn(`Post ${i + 1} missing field: ${field}`);
    }
  }
  return {
    day: post.day || '',
    postCaption: post.postCaption || '',
    imagePrompt: post.imagePrompt || '',
    videoIdea: post.videoIdea || '',
    contentFormat: contentFormats[post.day] || '',
    status: 'Planned'
  };
});

return [{ json: { posts: normalized } }];

// Split posts array into individual items for Sheet append
const posts = $('Parse & Normalize Output').first().json.posts;
return posts.map(p => ({ json: p }));

// Return the posts to the frontend
const posts = $('Parse & Normalize Output').first().json.posts;
return [{ json: posts }];

// Map Google Sheets rows to the format the frontend expects
const items = $input.all();
const contentFormats = {
  'Monday': 'Storytelling',
  'Tuesday': 'Statistics',
  'Wednesday': 'Customer Testimonial',
  'Thursday': 'How It Works',
  'Friday': 'Behind the Scenes',
  'Saturday': 'Thought Leadership'
};

const posts = items.map((item, i) => {
  const day = item.json.Day || item.json.day || '';
  return {
    day: day,
    contentFormat: item.json['Content Format'] || item.json.contentFormat || contentFormats[day] || '',
    postCaption: item.json.Caption || item.json.postCaption || '',
    imagePrompt: item.json['Image Prompt'] || item.json.imagePrompt || '',
    videoIdea: item.json['Video Idea'] || item.json.videoIdea || '',
    status: item.json.Status || item.json.status || 'Planned',
    rowIndex: i + 2
  };
});

return [{ json: posts }];
